    # Iterate over the array
    for i in range(len(nums)):
        # Swap the elements at indices i and j
        for j in range(i+1, len(nums)):
            # If the difference |nums[i] - nums[j]| <= limit
            if (nums[i] - nums[j]) <= limit:
                # Swap the elements at indices i and j
                dict[i] = nums[j]
                dict[j] = nums[i]

    # Return the dictionary
    return dict

