    return peaks

def count_complete_substrings(word, k):
    # Initialize a set to store the complete substrings
    complete_substrings = set()

    # Iterate through the word
    for i in range(len(word)):
        # Check if the current character is in the set
        if word[i] in complete_substrings:
            # If the current character is in the set, it is a complete substring
            complete_substrings.add(word[i])

            # If the current character is not in the set, it is not a complete substring
            if word[i] not in complete_substrings:
                # If the current character is not in the set, it is not a complete substring
                complete_substrings.remove(word[i])

            # If the current character is not in the set, it is not a complete substring
            if word[i] not in complete_substrings:
                return 0

    # Return the number of complete substrings
    return len(complete_substrings)

