def equalindromic(nums):
    """
    Return the minimum possible total cost to make nums equalindromic by performing any number of special moves.
    """
    if nums[0] == nums[1]:
        return 0
    else:
        return sum(nums[i] - nums[i] * (nums[i] - nums[i] + 1))

def remove_adjacent_almost_equal(word):
    # Initialize a set to keep track of adjacent almost-equal characters
    adjacent_almost_equal = set()

    # Iterate through the word
    for i in range(len(word)):
        # If the current character is not in the set, add it to the set
        if word[i] != word[i - 1]:
            adjacent_almost_equal.add(word[i])

    # If the current character is in the set, remove it
    if adjacent_almost_equal:
        adjacent_almost_equal.remove(word[i])

    # Return the minimum number of operations needed to remove all adjacent almost-equal characters
    return len(adjacent_almost_equal) - 1

