        if nums[i] == nums[i - 1]:
            # If the current element is the last element of the longest sequential prefix, it means the prefix is complete
            sum_of_longest_prefix[i] = sum_of_longest_prefix[i - 1] + 1

            # If the current element is not the last element of the longest sequential prefix, it means the prefix is incomplete
