def max_tastiness(N, X_1, Y_1, X_2, Y_2, X_N, Y_N):
    if N == 0:
        return 0
    if N == 1:
        return 0
    if N == 2:
        return X_1 * Y_1 + X_2 * Y_2
    if N == 3:
        return X_1 * Y_1 + X_2 * Y_2 + X_N * Y_N
    if N == 4:
        return X_1 * Y_1 + X_2 * Y_2 + X_N * Y_N + X_N * Y_N
    if N == 5:
        return X_1 * Y_1 + X_2 * Y_2 + X_N * Y_N + X_N * Y_N + X_N * Y_N
    return max(max_tastiness(N, X_1, Y_1, X_2, Y_2, X_N, Y_N), X_N, Y_N)

