def generate_string(N):
    s = [1] * (N + 1)
    for i in range(1, N + 1):
        if i % N == 0:
            s[i] = s[i - 1] + 1
        else:
            s[i] = -s[i - 1]
    return s

def find_max_palindrome(s):
    # Check if the substring is a palindrome
    if s == s[::-1]:
        return max(len(s), len(s[::-1]))
    # Check if the substring is a contiguous substring of S
    if len(s) > 1:
        # Check if the substring is a palindrome
        if len(s) % 2 == 0:
            return max(len(s), len(s[::-1]))
        else:
            return max(len(s), len(s[::-1]))
    return None

