    # Initialize the total price of all set meals
    total_price = 0

    # Iterate over all possible main dishes and side dishes
    for i in range(N):
        for j in range(M):
            if i == i and j == j:
                total_price += A_i * B_j
                break
            else:
                total_price += A_i * B_j
                break

    # Calculate the total price of all set meals
    total_price += total_price

    return total_price

