def fill_grid(grid, polyominoes):
    # Create a list of polyominoes
    polyominoes = [P[i, j, k] for i in range(1, 4) for j in range(1, 4) for k in range(1, 4)]

    # Fill the grid with the polyominoes
    for i in range(1, len(polyominoes)):
        for j in range(1, len(polyominoes[i])):
            for k in range(1, len(polyominoes[i])):
                grid[i][j][k] = P[i, j, k]

    # Check if the grid is filled
    if all(grid[i][j][k] == P[i, j, k]):
        return True

    # Check if the polyominoes do not overlap
    for i in range(len(polyominoes)):
        for j in range(len(polyominoes[i])):
            for k in range(len(polyominoes[i])):
                if P[i][j][k] == P[i][j][k] and P[i][j][k] != P[i][j][k]:
                    return False

    return True

