def find_most_frequent_letter(s):
    # Convert the string to lowercase
    s = s.lower()

    # Create a dictionary to store the frequency of each character
    freq_dict = {}

    # Iterate through the string
    for char in s:
        # If the character is not already in the dictionary, add it to the dictionary
        if char not in freq_dict:
            freq_dict[char] = freq_dict.get(char, 0) + 1

        # If the character is already in the dictionary, add it to the end of the dictionary
        if freq_dict[char] not in freq_dict[char]:
            freq_dict[char] = freq_dict[char] + 1

    # Find the earliest character in alphabetical order
    # If the dictionary is empty, return the first character
    if freq_dict[0] == 'a':
        return 'a'
    else:
        return freq_dict[0] + 1

