    # Check if the length of S is between 3 and 100
    if len(S) < 3 or len(S) > 100:
        return "The length of S is too small or too large."

    # Check if all characters but one of S are the same
    if len(S) % 2 == 1:
        return "The length of S is too small or too large."

    # Check if the second character of S differs from the first and third characters
    if len(S[0]) != len(S[1]) != len(S[2]):
        return "The second character of S differs from the first and third characters."

    # Find x such that the x-th character of S differs from all other characters
