def distance(s1, s2):
    # Create a dictionary to store the minimum distance
    min_dist = {}

    # Iterate through each character in s1
    for i in range(1, s1.length):
        # If the character is not in s2, add it to the dictionary
        if s2[i] != s1[i]:
            min_dist[s1[i]] = min(min_dist[s1[i]] + min_dist[s2[i]] + s2[i], s1[i])

        # If the character is in s2, add it to the dictionary
        if s2[i] in min_dist[s1[i]]:
            min_dist[s1[i]] = min(min_dist[s1[i]] + s2[i], s1[i])

    # If the character is not in s1, add it to the dictionary
    if s1[i] not in min_dist[s2[i]]:
        min_dist[s1[i]] = min(min_dist[s1[i]] + s2[i], s1[i])

    return min_dist[s1]

